.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 49px;
  padding: 13px 24px;
  border-radius: 7px;
  background: var(--ink, #243b30);
  color: var(--paper, #f6f6ef);
  font-weight: 500;
  transition:
    background 0.2s,
    transform 0.2s,
    box-shadow 0.2s;
}
.ds-button:hover {
  background: #36543f;
  box-shadow: var(--elevation, 0 10px 30px #243b3010);
}
.ds-button{font-family:var(--body, "DM Sans Variable", sans-serif);font-size:15px;border:0;cursor:pointer;text-decoration:none}.ds-button:focus-visible{outline:2px solid #537a3c;outline-offset:4px;}.ds-button:active{transform:translateY(1px)}.ds-button:disabled{cursor:default;opacity:.5}@media(prefers-reduced-motion:reduce){.ds-button{transition:none}}

