.ds-icon-button {
  width: 44px;
  min-width: 44px;
  height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  transition: background 0.2s;
}
.ds-icon-button:hover {
  background: #e6eadc;
}
.ds-icon-button{border:0;background:none;color:var(--ink, #243b30);cursor:pointer}.ds-icon-button:focus-visible{outline:2px solid #537a3c;outline-offset:4px;}.ds-icon-button:active{transform:translateY(1px)}@media(prefers-reduced-motion:reduce){.ds-icon-button{transition:none}}

.ds-field-label {
  display: block;
  font-size: 13px;
  margin: 20px 0;
}
.ds-field-label input,
.ds-field-label textarea {
  display: block;
  width: 100%;
  background: #fff;
  border: 1px solid var(--line, #dce0d5);
  padding: 12px;
  border-radius: 5px;
  margin-top: 10px;
  min-height: 48px;
}
.ds-field-label{font-family:var(--body, "DM Sans Variable", sans-serif);color:var(--ink, #243b30)}.ds-field-label input{font:inherit;max-width:100%;caret-color:#537a3c}.ds-field-label input:focus-visible{outline:2px solid #537a3c;outline-offset:4px;}

.ds-desktop-nav {
  display: flex;
  align-items: center;
  gap: 28px;
  height: 100%;
  margin-left: auto;
}
.ds-desktop-nav a {
  position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  height: 100%;
  color: var(--muted, #647064);
}
.ds-desktop-nav a.ds-active {
  color: var(--ink, #243b30);
  font-weight: 600;
}
.ds-desktop-nav a.ds-active:after {
  content: "";
  position: absolute;
  bottom: 0;
  height: 2px;
  background: var(--ink, #243b30);
  left: 0;
  right: 0;
}
.ds-desktop-nav{height:90px;font-family:var(--body, "DM Sans Variable", sans-serif);border-bottom:1px solid var(--line, #dce0d5);margin-left:0}.ds-desktop-nav a{text-decoration:none}.ds-desktop-nav a:focus-visible{outline:2px solid #537a3c;outline-offset:4px;}

.ds-collection-tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 25px;
}
.ds-collection-tabs > button {
  min-height: 44px;
  border: 1px solid #d4dcc8;
  display: flex;
  align-items: center;
  gap: 9px;
  border-radius: 5px;
  font-size: 12px;
  padding: 10px 16px;
}
.ds-collection-tabs > button.ds-active {
  background: var(--ink, #243b30);
  color: var(--paper, #f6f6ef);
  border-color: var(--ink, #243b30);
}
.ds-collection-tabs > button:not(.ds-active):hover {
  background: #e5ebd9;
}
.ds-collection-tabs > button > span {
  font-size: 10px;
  opacity: 0.75;
}
.ds-collection-tabs{font-family:var(--body, "DM Sans Variable", sans-serif);color:var(--ink, #243b30)}.ds-collection-tabs>button{background:none;color:inherit;cursor:pointer}.ds-collection-tabs>button:focus-visible{outline:2px solid #537a3c;outline-offset:4px;}.ds-collection-tabs>button:active{transform:translateY(1px)}

.ds-place-card {
  min-width: 0;
}
.ds-card-visual {
  position: relative;
  aspect-ratio: 1.66;
  border-radius: 10px;
  overflow: hidden;
  background: #d1d8bb;
}
.ds-card-visual > a {
  display: block;
  height: 100%;
}
.ds-fallback-content {
  display: flex;
  height: 100%;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 14px;
  color: #506343;
  background: linear-gradient(130deg, #dce2c6, #b2c0a5);
}
.ds-fallback-content > span {
  font-family: var(--display, "Manrope Variable", sans-serif);
  font-size: 22px;
  letter-spacing: -0.025em;
  max-width: 80%;
  text-align: center;
}
.ds-fallback-content > small {
  font-size: 11px;
  color: #526246;
}
.ds-match-badge {
  position: absolute;
  left: 14px;
  top: 14px;
  display: flex;
  align-items: center;
  gap: 5px;
  min-height: 27px;
  font-size: 10px;
  font-weight: 600;
  background: var(--paper, #f6f6ef);
  padding: 6px 9px;
  border-radius: 4px;
  color: var(--ink, #243b30);
}
.ds-card-content {
  padding: 17px 1px 0;
}
.ds-place-category {
  color: var(--muted, #647064);
  font-size: 10px;
  line-height: 1.5;
}
.ds-place-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 6px;
  min-height: 36px;
}
.ds-place-title h3 {
  font-size: 23px;
  font-weight: 550;
}
.ds-place-title:hover {
  color: #637d43;
}
.ds-card-reason {
  font-size: 12px;
  color: var(--muted, #647064);
  line-height: 1.7;
  margin-top: 16px;
}
.ds-card-bottom {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--muted, #647064);
  margin-top: 16px;
  border-top: 1px solid var(--line, #dce0d5);
  padding-top: 11px;
  gap: 10px;
}
.ds-place-card{font-family:var(--body, "DM Sans Variable", sans-serif);color:var(--ink, #243b30)}.ds-place-card p,.ds-place-card h3{margin:0}.ds-place-card a{text-decoration:none;color:inherit}.ds-place-title h3{font-family:var(--display, "Manrope Variable", sans-serif)}.ds-place-card a:focus-visible{outline:2px solid #537a3c;outline-offset:4px;}

.ds-quick-controls {
  display: flex;
  align-items: center;
  border: 1px solid #d3d9c7;
  border-radius: 8px;
  width: max-content;
  max-width: 100%;
  padding: 0 3px;
  background: #ffffff50;
}
.ds-quick-controls > label {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  position: relative;
  min-height: 45px;
}
.ds-quick-controls > label + label:before {
  content: "";
  position: absolute;
  height: 16px;
  background: #d5ddc9;
  width: 1px;
  left: 0;
}
.ds-quick-controls select {
  font-size: 12px;
  padding: 0;
  max-width: 112px;
  font-weight: 450;
}
.ds-quick-controls > button {
  min-height: 44px;
  width: 39px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-left: 1px solid var(--line, #dce0d5);
}
.ds-quick-controls > button.ds-selected {
  background: var(--accent, #d9eb84);
  border-radius: 0 6px 6px 0;
}
.ds-quick-controls{font-family:var(--body, "DM Sans Variable", sans-serif);color:var(--ink, #243b30)}.ds-quick-controls select,.ds-quick-controls button{border:0;background:none;color:inherit;cursor:pointer}.ds-quick-controls select:focus-visible,.ds-quick-controls button:focus-visible{outline:2px solid #537a3c;outline-offset:4px;}.ds-quick-controls button:active{transform:translateY(1px)}

.ds-detail-action-panel {
  align-self: start;
  position: sticky;
  top: 25px;
  background: #e7ecda;
  padding: 27px;
  border-radius: 12px;
}
.ds-panel-label {
  font-size: 11px;
  color: #5b6c47;
}
.ds-detail-action-panel h2 {
  font-size: 27px;
  margin-top: 15px;
}
.ds-detail-action-panel > p:not(.ds-fine-print) {
  font-size: 12px;
  color: #5d6c4f;
  margin: 18px 0;
  display: flex;
  gap: 7px;
  align-items: center;
}
.ds-detail-action-panel .ds-button {
  font-size: 13px;
  margin-top: 10px;
}
