}
.ds-detail-action-panel{font-family:var(--body, "DM Sans Variable", sans-serif);color:var(--ink, #243b30);position:static}.ds-detail-action-panel h2{font-family:var(--display, "Manrope Variable", sans-serif);font-weight:600;letter-spacing:-.025em;line-height:1.25;margin-bottom:0}.ds-button{font-family:var(--body, "DM Sans Variable", sans-serif);font-size:15px;border:0;cursor:pointer;text-decoration:none}.ds-button:focus-visible{outline:2px solid #537a3c;outline-offset:4px;}.ds-button:active{transform:translateY(1px)}.ds-button:disabled{cursor:default;opacity:.5}@media(prefers-reduced-motion:reduce){.ds-button{transition:none}}
